pm.test("M1-BE-01 - Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("M1-BE-01 - Response is JSON", function () {
    pm.expect(pm.response.headers.get("Content-Type"))
        .to.include("application/json");
});

pm.test("M1-BE-01 - Authentication token is returned", function () {
    const jsonData = pm.response.json();
    pm.expect(jsonData.token).to.be.a("string");
    pm.expect(jsonData.token.length).to.be.above(0);
});

pm.test("M1-BE-01 - User details are returned", function () {
    const jsonData = pm.response.json();
    pm.expect(jsonData.userId).to.exist;
    pm.expect(jsonData.fullName).to.be.a("string");
    pm.expect(jsonData.role).to.be.a("string");
});
const loginData = pm.response.json();

pm.environment.set("adminToken", loginData.token);
pm.environment.set("adminUserId", loginData.userId);

